#define CHECK(x) do{if(!(x))throw std::runtime_error(#x);}while(false)
int main(){try{using namespace moon;const PickerQuantization q{12,5};CHECK(pickerNearestPreset(18.,pickerHuePresets)==12);CHECK(pickerNearestPreset(7.,pickerColorPresets)==5);CHECK(pickerNearestPreset(std::numeric_limits<double>::quiet_NaN(),pickerHuePresets)==0);CHECK(pickerQuantHue(15,q)==30&&pickerQuantHue(-15,q)==0&&pickerQuantHue(345,q)==0);CHECK(pickerQuantHue(344.999,q)==330);CHECK(pickerQuantColor(.199999,q)==0&&pickerQuantColor(.2,q)==.25&&pickerQuantColor(1,q)==1);CHECK(pickerQuantCell(0,q)==.1&&pickerQuantCell(1,q)==.9);CHECK(1-pickerQuantColor(.2,q)==.75&&pickerQuantColor(1-.2,q)==1);const auto hs=pickerQuantInput(ColorPickerScheme::HsSquare,{17,.3,.4},.3,.3,q);CHECK(hs.h==90&&hs.s==.75&&hs.v==.4);const auto sv=pickerQuantInput(ColorPickerScheme::SvSquare,{17,.3,.4},.3,.2,q);CHECK(sv.h==17&&sv.s==.25&&sv.v==.75);const auto weights=pickerQuantTriangle({1./3,1./3,1./3},q);CHECK(weights.tip==.5&&weights.white==.25&&weights.black==.25);const auto vector=pickerQuantWheel(.99,0,q);CHECK(std::abs(vector.x-.8)<1e-12&&std::abs(vector.y)<1e-12);const auto corner=pickerQuantWheel(.99,.99,q,pickerQuantWheelSafe(q));CHECK(std::abs(std::hypot(corner.x,corner.y)-(1-10./256))<1e-12);CHECK(!pickerQuantWheelBeginHit(.85,.85,q));const auto normal=pickerNormalQuantize(.3,.4,12,5);CHECK(std::abs(normal.x-.25)<1e-12&&std::abs(normal.y-std::sqrt(3.)/4)<1e-12);CHECK(pickerNormalMapColorAt(normal.x,normal.y)==0xffdd489fu);std::vector<std::uint32_t> pixels{0xff000000u,0,0xffffffffu};std::vector<unsigned char> mask{1,0,1};pickerQuantOutline(pixels,mask,3,1);CHECK(pixels[1]==0xffe0e0e0u);PickerRole role;role.sync(0x37112233u);pickerQuantSetStrip(role,ColorPickerScheme::Wheel,.3,q);CHECK(role.hsv.v==.25&&role.color>>24==55);pickerQuantSetAlphaValue(role,128,q);CHECK(role.color>>24==128);role.hsv.v=0;role.emit();CHECK(pickerQuantStripValue(ColorPickerScheme::Wheel,role.hsv,q)==100);pickerQuantSetStripValue(role,ColorPickerScheme::Wheel,101,q);CHECK(role.hsv.v==0);PickerQuantTriangleGeometry geometry;geometry.ensure(9,9,q);const auto* cached=geometry.weights.data();geometry.ensure(9,9,{24,5});CHECK(geometry.weights.data()==cached&&geometry.steps==5);geometry.ensure(9,9,{24,9});CHECK(geometry.steps==9);std::cout<<"Picker quantization legacy rounding/boundary/scheme fixtures passed\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
